public class ReportGenerator {
    public String buildOrderReport(List<Order> orders) {
        var sb = new StringBuilder(500); // pre-size for performance

        sb.append("=== Order Report ===").append("\n");
        sb.append("Generated: ").append(LocalDateTime.now()).append("\n\n");

        for (var order : orders) {
            sb.append("Order #").append(order.id())
              .append(": ").append(order.itemName())
              .append(" - $").append(order.price())
              .append("\n");
        }

        sb.insert(0, "DRAFT - "); // prepend at start
        sb.delete(sb.length() - 1, sb.length()); // remove trailing newline

        return sb.toString(); // extract final string
    }
}

record Order(Long id, String itemName, double price) {}

public class CsvExporter {
    public String exportOrders(List<Order> orders) {
        // Estimate: 80 chars per order line (ID, name, price, date)
        int estimatedSize = orders.size() * 80 + 100; // +100 for header
        var sb = new StringBuilder(estimatedSize); // pre-size to avoid resizing

        sb.append("OrderID,ItemName,Price,Date\n");

        for (var order : orders) {
            sb.append(order.id()).append(",")
              .append(order.itemName()).append(",")
              .append(order.price()).append(",")
              .append(order.orderDate()).append("\n");
        }

        return sb.toString();
    }
}

record Order(Long id, String itemName, double price, LocalDate orderDate) {}

public class InputSanitizer {
    public String sanitizeAndFormat(String userInput) {
        // Convert String to StringBuilder for modification
        var sb = new StringBuilder(userInput);

        // Remove leading/trailing whitespace by manipulating indices
        while (sb.length() > 0 && Character.isWhitespace(sb.charAt(0))) {
            sb.deleteCharAt(0);
        }
        while (sb.length() > 0 && Character.isWhitespace(sb.charAt(sb.length() - 1))) {
            sb.deleteCharAt(sb.length() - 1);
        }

        // Replace multiple spaces with single space
        for (int i = 0; i < sb.length() - 1; i++) {
            if (sb.charAt(i) == ' ' && sb.charAt(i + 1) == ' ') {
                sb.deleteCharAt(i);
                i--; // recheck current position
            }
        }

        return sb.toString(); // Convert back to String once, at the end
    }
}
